mapper.select:
SELECT pp.id, pp.code, pp.title, (SELECT pm.file_url FROM product_media pm WHERE pm.product_id = pp.id AND pm.file_type = 1 ORDER BY pm.img_pos, pm.id LIMIT 1) AS headImgUrl, COALESCE(( SELECT sp.eval_with_image_count FROM product_bind_relation pbr JOIN source_product sp ON sp.id = pbr.source_productId WHERE pbr.product_id = pp.id AND pbr.is_deleted = 0 LIMIT 1 ), 0) AS sourceEvalCount, COALESCE(( SELECT COUNT(*) FROM brush_order bo WHERE bo.product_id = CONCAT('', pp.id) AND bo.is_evaluated = 1 ), 0) AS platformEvalCount, GREATEST( COALESCE(( SELECT sp.eval_with_image_count FROM product_bind_relation pbr JOIN source_product sp ON sp.id = pbr.source_productId WHERE pbr.product_id = pp.id AND pbr.is_deleted = 0 LIMIT 1 ), 0) - COALESCE(( SELECT COUNT(*) FROM brush_order bo WHERE bo.product_id = CONCAT('', pp.id) AND bo.is_evaluated = 1 ), 0), 0) AS gap FROM platform_product pp WHERE pp.platform_type = #{platformType}
AND (pp.title LIKE CONCAT('%', #{keyword}, '%') OR pp.code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY pp.id
